package es.scafftrix.factory.repository;

import es.scafftrix.factory.domain.ConfigFormat;
import es.scafftrix.factory.domain.Project;
import es.scafftrix.factory.domain.ProjectCoordinates;
import es.scafftrix.factory.domain.ProjectStatus;
import es.scafftrix.factory.domain.ProjectType;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Integration test against a real in-memory H2 schema, generated by Hibernate from the
 * entity. It proves the persistence layer the CRUD relies on: generated identifiers,
 * timestamp lifecycle, optimistic-lock version, update and delete.
 */
@DataJpaTest
class ProjectRepositoryIntegrationTest {

    @Autowired
    private ProjectRepository repository;

    private Project project(ProjectType type, String name, String baseName, String artifactId) {
        return new Project(name,
                new ProjectCoordinates(baseName, "es.scafftrix", artifactId,
                        "es.scafftrix." + baseName, "1.0.0-SNAPSHOT"),
                "desc", type, type.technologyStack(), "4.1.1", ConfigFormat.PROPERTIES);
    }

    @Test
    void persistsAProjectWithGeneratedIdAndTimestamps() {
        Project saved = repository.saveAndFlush(
                project(ProjectType.SPRING_BOOT, "Customer Management", "customerManagement", "customer-management"));

        assertThat(saved.getId()).isNotNull();
        assertThat(saved.getStatus()).isEqualTo(ProjectStatus.CREATED);
        assertThat(saved.getCreatedAt()).isNotNull();
        assertThat(saved.getUpdatedAt()).isNotNull();
        assertThat(saved.getEntityVersion()).isZero();

        Project found = repository.findById(saved.getId()).orElseThrow();
        assertThat(found.getName()).isEqualTo("Customer Management");
        assertThat(found.getArtifactPath()).isNull();
    }

    @Test
    void storesEveryProjectType() {
        repository.saveAndFlush(project(ProjectType.SPRING_BOOT, "Boot", "boot", "boot"));
        repository.saveAndFlush(project(ProjectType.SPRING_BATCH, "Batch", "batch", "batch"));
        repository.saveAndFlush(project(ProjectType.SPRING_MICROSERVICE, "Micro", "micro", "micro"));

        assertThat(repository.countByProjectType(ProjectType.SPRING_BOOT)).isEqualTo(1);
        assertThat(repository.countByProjectType(ProjectType.SPRING_BATCH)).isEqualTo(1);
        assertThat(repository.countByProjectType(ProjectType.SPRING_MICROSERVICE)).isEqualTo(1);
    }

    @Test
    void updatePersistsTheNewMetadataAndBumpsTheVersion() {
        Project saved = repository.saveAndFlush(
                project(ProjectType.SPRING_BOOT, "Original", "original", "original"));

        saved.updateMetadata("Renamed", "2.0.0", null);
        repository.saveAndFlush(saved);

        Project reloaded = repository.findById(saved.getId()).orElseThrow();
        assertThat(reloaded.getName()).isEqualTo("Renamed");
        assertThat(reloaded.getVersion()).isEqualTo("2.0.0");
        assertThat(reloaded.getDescription()).isNull();
        assertThat(reloaded.getEntityVersion()).isPositive();
    }

    @Test
    void deleteRemovesTheRecord() {
        Project saved = repository.saveAndFlush(
                project(ProjectType.SPRING_BOOT, "Temp", "temp", "temp"));

        repository.delete(saved);
        repository.flush();

        assertThat(repository.findById(saved.getId())).isEmpty();
    }
}
